/* Preserve the Cartesian boundary cases formerly generated by grid.awk.
   C arithmetic supplies an independent oracle for each exported entry. */
#define _POSIX_C_SOURCE 200809L

#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
  char call[512];
  char want[96];
} Row;

static Row rows[616];
static size_t count;
static const char *program = "examples/entries.lang";
static const uint64_t values[] = {
  0, 1, 2, 3, 5, 7, UINT64_C(4294967295), UINT64_C(4294967296),
  UINT64_C(4294967297), UINT64_MAX
};

static int add_row(const char *name, uint64_t a, uint64_t b, int two, int none, uint64_t value) {
  if (count == sizeof rows / sizeof rows[0]) return 0;
  Row *row = &rows[count++];
  if (two) snprintf(row->call, sizeof row->call, "%s %" PRIu64 " %" PRIu64, name, a, b);
  else snprintf(row->call, sizeof row->call, "%s %" PRIu64, name, a);
  if (none) snprintf(row->want, sizeof row->want, "none\n");
  else snprintf(row->want, sizeof row->want, "%" PRIu64 "\n", value);
  return 1;
}

static int write_calls(void) {
  FILE *calls = fopen("build/entry-grid.calls", "w");
  if (calls == NULL) return 0;
  int ok = 1;
  for (size_t i = 0; i < count && ok; i++) ok = fprintf(calls, "%s\n", rows[i].call) >= 0;
  return fclose(calls) == 0 && ok;
}

static int make_rows(void) {
  size_t i, j;
  for (i = 0; i < sizeof values / sizeof values[0]; i++) {
    uint64_t a = values[i];
    if (!add_row("cheap", a, 0, 0, 0, a <= 100)) return 0;
    /* Loop counts keep the original grid's six small values. */
    if (i < 6u && !add_row("square", a, 0, 0, 0, a * a)) return 0;
    for (j = 0; j < sizeof values / sizeof values[0]; j++) {
      uint64_t b = values[j];
      int over = a > UINT64_MAX - b;
      if (!add_row("addPrice", a, b, 1, over, over ? 0 : a + b) ||
          !add_row("discount", a, b, 1, a < b, a < b ? 0 : a - b) ||
          !add_row("ratio", a, b, 1, b == 0, b == 0 ? 0 : a / b) ||
          !add_row("remainder", a, b, 1, b == 0, b == 0 ? 0 : a % b)) return 0;
      for (unsigned flag = 0; flag < 2u; flag++) {
        if (count == sizeof rows / sizeof rows[0]) return 0;
        Row *row = &rows[count++];
        snprintf(row->call, sizeof row->call, "pick %u %" PRIu64 " %" PRIu64, flag, a, b);
        snprintf(row->want, sizeof row->want, "%" PRIu64 "\n", flag ? a : b);
      }
    }
  }
  if (count != sizeof rows / sizeof rows[0]) return 0;
  return write_calls();
}

static int result(FILE *stream, const char *backend, size_t i, size_t *failures) {
  char line[256];
  int got = fgets(line, sizeof line, stream) != NULL;
  if (got && strcmp(line, rows[i].want) == 0) return 1;
  if ((*failures)++ < 5u)
    fprintf(stderr, "FAIL entry grid %s %s: %s: want %s, got %s", backend, program, rows[i].call,
            rows[i].want, got ? line : "no result\n");
  return 0;
}

static int check_eval(void) {
  size_t failures = 0;
  for (size_t i = 0; i < count; i++) {
    char command[1024], extra[256];
    snprintf(command, sizeof command,
             "build/langc --kit eval %s %s 2>build/entry-grid.err", program, rows[i].call);
    FILE *stream = popen(command, "r");
    if (stream == NULL) return 0;
    int ok = result(stream, "eval", i, &failures);
    if (fgets(extra, sizeof extra, stream) != NULL || ferror(stream)) ok = 0;
    if (pclose(stream) != 0) ok = 0;
    if (!ok) return 0;
  }
  return 1;
}

static int check_backend(const char *backend, const char *command) {
  FILE *stream = popen(command, "r");
  char extra[256];
  size_t failures = 0;
  int ok = stream != NULL;
  if (stream == NULL) return 0;
  for (size_t i = 0; i < count; i++) {
    if (!result(stream, backend, i, &failures)) ok = 0;
  }
  if (fgets(extra, sizeof extra, stream) != NULL || ferror(stream)) ok = 0;
  if (pclose(stream) != 0) ok = 0;
  return ok;
}

static int build_abi(void) {
  char command[384];
  snprintf(command, sizeof command, "build/langc --kit abi %s --text >build/entry-grid.abi", program);
  return system(command) == 0;
}

static int build_program(const char *target, const char *out) {
  char command[384];
  snprintf(command, sizeof command, "build/langc --kit build %s %s %s", program, target, out);
  return system(command) == 0;
}

static int check_targets(int gpu) {
  if (count == 0) return 1;
  if (!build_program("-o", "build/entry-grid.wasm") ||
      !build_program("--js", "build/entry-grid.mjs") ||
      !build_abi() ||
      !check_backend("wasm", "build/wasmtool build/entry-grid.wasm build/entry-grid.abi <build/entry-grid.calls") ||
      !check_backend("js", "build/jstool build/entry-grid.mjs build/entry-grid.abi <build/entry-grid.calls") ||
      (gpu && (!build_program("--wgsl", "build/entry-grid.wgsl") ||
               !check_backend("wgsl", "build/wgsltool build/entry-grid.wgsl build/entry-grid.abi <build/entry-grid.calls")))) {
    fprintf(stderr, "FAIL entry grid: a build or backend check failed for %s\n", program);
    return 0;
  }
  return 1;
}

/* These fixtures also used grid.awk before the port. Recover their exact
   Nat/Flag Cartesian grid from the IR, including its smaller loop bounds. */
typedef struct {
  char name[128];
  unsigned flag[32];
  size_t params;
  int loop;
} Function;

static int function_line(Function *fn, char *line) {
  char *open = strchr(line, '('), *close = strchr(line, ')');
  if (sscanf(line, "func %127s", fn->name) != 1 || open == NULL || close == NULL || close < open) return 0;
  if (strspn(fn->name, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_") != strlen(fn->name)) return 0;
  fn->params = 0;
  fn->loop = 0;
  for (char *p = open + 1; p < close;) {
    while (p < close && (*p == ' ' || *p == ',')) p++;
    if (p == close) break;
    if (fn->params == sizeof fn->flag / sizeof fn->flag[0]) return 0;
    int flag = strncmp(p, "flag", 4) == 0;
    size_t width = flag ? 4u : 3u;
    if (!flag && strncmp(p, "nat", 3) != 0) return 0;
    p += width;
    if (p > close || (p < close && *p != ' ' && *p != ',')) return 0;
    fn->flag[fn->params++] = (unsigned)flag;
  }
  return 1;
}

static int grid_calls(const Function *fn, size_t param, char *call, size_t len) {
  if (param == fn->params) {
    char command[1024], extra[64];
    if (count == sizeof rows / sizeof rows[0]) return 0;
    Row *row = &rows[count++];
    snprintf(row->call, sizeof row->call, "%s", call);
    snprintf(command, sizeof command, "build/langc --kit eval %s %s 2>build/entry-grid.err", program, call);
    FILE *stream = popen(command, "r");
    if (stream == NULL) return 0;
    int ok = fgets(row->want, sizeof row->want, stream) != NULL;
    if (fgets(extra, sizeof extra, stream) != NULL || ferror(stream)) ok = 0;
    if (pclose(stream) != 0) ok = 0;
    return ok;
  }
  size_t n = fn->flag[param] ? 2u : fn->loop ? 6u : sizeof values / sizeof values[0];
  for (size_t i = 0; i < n; i++) {
    int wrote = snprintf(call + len, sizeof rows[0].call - len, " %" PRIu64, values[i]);
    if (wrote < 0 || (size_t)wrote >= sizeof rows[0].call - len ||
        !grid_calls(fn, param + 1u, call, len + (size_t)wrote)) return 0;
  }
  return 1;
}

static int fixture_rows(void) {
  Function functions[128];
  size_t functions_len = 0;
  char command[256], line[4096];
  snprintf(command, sizeof command, "build/langc --kit ir %s 2>build/entry-grid.err", program);
  FILE *stream = popen(command, "r");
  if (stream == NULL) return 0;
  int ok = 1;
  while (fgets(line, sizeof line, stream) != NULL) {
    if (!ok) continue;
    if (strncmp(line, "func ", 5) == 0) {
      ok = functions_len < sizeof functions / sizeof functions[0] && function_line(&functions[functions_len], line);
      functions_len += (size_t)ok;
    } else if (functions_len != 0) {
      char *p = line + strspn(line, " \t");
      if (strncmp(p, "repeat ", 7) == 0 || strncmp(p, "while ", 6) == 0) functions[functions_len - 1u].loop = 1;
    }
  }
  if (ferror(stream)) ok = 0;
  if (pclose(stream) != 0) ok = 0;
  if (!ok) return 0;
  count = 0;
  for (size_t i = 0; i < functions_len; i++) {
    char call[sizeof rows[0].call];
    snprintf(call, sizeof call, "%s", functions[i].name);
    if (!grid_calls(&functions[i], 0, call, strlen(call))) return 0;
  }
  return write_calls();
}

/* Fixed arithmetic identities supply an oracle independent of langc and
   cover every word limb, the full product, overflow and a zero divisor. */
static int word_rows(void) {
#define MAX_WORD "0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffu"
#define MAX_RESULT "115792089237316195423570985008687907853269984665640564039457584007913129639935u\n"
  static const Row cases[] = {
    {"nonzeroFlag 0u", "0\n"},
    {"nonzeroFlag 1u", "1\n"},
    {"nonzeroFlag 18446744073709551616u", "1\n"},
    {"nonzeroFlag 340282366920938463463374607431768211456u", "1\n"},
    {"nonzeroFlag 6277101735386680763835789423207666416102355444464034512896u", "1\n"},
    {"nonzeroFlag " MAX_WORD, "1\n"},
    {"product 0u " MAX_WORD, "0u\n"},
    {"product " MAX_WORD " 0u", "0u\n"},
    {"product 1u " MAX_WORD, MAX_RESULT},
    {"product 6u 7u", "42u\n"},
    {"product 4294967295u 4294967295u", "18446744065119617025u\n"},
    {"product 18446744073709551616u 18446744073709551616u", "340282366920938463463374607431768211456u\n"},
    {"product 340282366920938463463374607431768211456u 340282366920938463463374607431768211456u", "none\n"},
    {"product " MAX_WORD " 2u", "none\n"},
    {"quotient 7u 3u 2u", "10u\n"},
    {"quotient " MAX_WORD " " MAX_WORD " " MAX_WORD, MAX_RESULT},
    {"quotient " MAX_WORD " 2u 2u", MAX_RESULT},
    {"quotient " MAX_WORD " 2u 1u", "none\n"},
    {"quotient 1u 1u 0u", "none\n"},
    {"quotient 0u " MAX_WORD " " MAX_WORD, "0u\n"},
    {"quotient 340282366920938463463374607431768211456u 340282366920938463463374607431768211456u " MAX_WORD, "1u\n"},
    {"quotient 340282366920938463463374607431768211456u 340282366920938463463374607431768211456u 2u",
     "57896044618658097711785492504343953926634992332820282019728792003956564819968u\n"},
    {"quotient 0xfffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffeu 0xfffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffeu " MAX_WORD,
     "115792089237316195423570985008687907853269984665640564039457584007913129639933u\n"}
  };
#undef MAX_WORD
#undef MAX_RESULT
  program = "test/wasm/word-options.lang";
  count = sizeof cases / sizeof cases[0];
  if (count > sizeof rows / sizeof rows[0]) return 0;
  memcpy(rows, cases, sizeof cases);
  return write_calls();
}

int main(int argc, char **argv) {
  static const char *const fixtures[] = {
    "examples/algebra.lang", "examples/equality.lang", "examples/formers.lang",
    "examples/functions.lang", "examples/laws.lang", "examples/monad.lang",
    "examples/sigma.lang", "examples/universes.lang", "test/ir/spine.lang",
    "test/ir/lazy.lang", "test/ir/proof-trap.lang"
  };
  int gpu = argc == 2 && strcmp(argv[1], "--gpu") == 0;
  if (argc != 1 && !gpu) return 2;
  if (!make_rows() || !check_eval() || !check_targets(gpu)) {
    fputs("FAIL entry grid: cannot validate all 616 independent rows\n", stderr);
    return 1;
  }
  printf("entry boundary grid: %zu rows, evaluator/wasm/js%s passed\n", count, gpu ? "/wgsl" : "");
  size_t legacy = 0;
  for (size_t i = 0; i < sizeof fixtures / sizeof fixtures[0]; i++) {
    program = fixtures[i];
    if (!fixture_rows() || !check_targets(gpu)) {
      fprintf(stderr, "FAIL fixture boundary grid: %s\n", program);
      return 1;
    }
    legacy += count;
  }
  printf("fixture boundary grid: %zu rows, wasm/js%s passed\n", legacy, gpu ? "/wgsl" : "");
  if (!word_rows() || !check_eval() || !check_targets(gpu)) {
    fputs("FAIL word boundary grid\n", stderr);
    return 1;
  }
  printf("word boundary grid: %zu rows, evaluator/wasm/js%s passed\n", count, gpu ? "/wgsl" : "");
  return 0;
}
